import java.util.*;

class Solution {
    public int maxArea(int[] walls) {
        int i = 0, j = walls.length - 1, best = 0;
        while (i < j) {
            int h = Math.min(walls[i], walls[j]);
            best = Math.max(best, (j - i) * h);
            if (walls[i] < walls[j]) i++;  // the shorter wall limits the tank, drop it
            else j--;
        }
        return best;
    }
}

